ROOT = Path(__file__).resolve().parents[1]
spec = spec_from_file_location('mentor_fixture', ROOT/'examples/generate_mentor_demo.py')
fixture = module_from_spec(spec)
spec.loader.exec_module(fixture)


def indexed(report):
    conn = sqlite3.connect(':memory:')
    conn.execute('CREATE TABLE rows(kind TEXT,n INTEGER,pii_type TEXT,location TEXT,value TEXT,data TEXT,PRIMARY KEY(kind,n))')
    conn.execute("CREATE INDEX evidence_ids ON rows(kind,json_extract(data,'$.evidence_id'))")
    create_index(conn)
    for kind in ('packet_evidence','stream_evidence','field_evidence','http_evidence','findings','flows'):
        for n, row in enumerate(report[kind]):
            conn.execute('INSERT INTO rows VALUES(?,?,?,?,?,?)', (kind,n,'','','',json.dumps(row)))
            index_row(conn,kind,row,n)
    return conn


@pytest.fixture
def evidence(tmp_path):
    path = tmp_path/'demo.pcap'
    oracle = fixture.write_demo(path)
    report = analyze(path)
    conn = indexed(report)
    try:
        yield path, oracle, report, conn
    finally:
        conn.close()


def test_transactions_interim_direction_and_pagination(evidence):
    _, _, report, conn = evidence
    first = conversations(conn, limit=1)
    assert first['total'] == 2 and len(first['items']) == 1
    tx = first['items'][0]
    assert [m['message_type'] for m in tx['messages']] == ['request','response','response']
    assert [m['status'] for m in tx['messages']] == [None,100,200]
    assert tx['messages'][1]['interim_response'] is True
    assert len({m['http_request_id'] for m in tx['messages']}) == 1
    for m in tx['messages']:
        assert m['session'] == 1
        assert m['client'] == {'ip':fixture.CLIENT,'port':fixture.SPORT}
        assert m['server'] == {'ip':fixture.SERVER,'port':fixture.DPORT}
        assert m['source'] == (m['client'] if m['message_type']=='request' else m['server'])
        assert m['association_basis'] == 'directional_fifo_best_effort'
    assert conversations(conn, offset=1, limit=1)['items'][0]['transaction_id'] != tx['transaction_id']
    assert conversations(conn, offset=2)['items'] == []
    default = json.dumps(first)
    assert '/profile' not in default and 'fictional-demo-only-token' not in default
    for bad in ({'limit':101},{'offset':-1},{'limit':0}):
        with pytest.raises(ValueError): conversations(conn,**bad)


def test_finding_field_packet_file_join_has_independent_exact_bytes(evidence):
    path, oracle, report, conn = evidence
    finding = next(f for f in report['findings'] if f['pii_type']=='EMAIL' and f['http_message_id']==report['http_evidence'][0]['http_message_id'])
    fid = finding['evidence']['field_ids'][0]
    result = investigation(conn,message_id=finding['http_message_id'],field_id=fid,limit=1)
    assert result['selected_field']['granularity'] == 'exact_stream_range'
    assert result['findings']['total'] >= 1
    assert result['findings']['items'][0]['evidence']['raw_detection_span'] == 'unavailable'
    refs = result['source_ranges']
    assert [r['frame_index'] for r in refs] == oracle['email_support_frames']
    raw = path.read_bytes()
    assert b''.join(raw[r['file_start']:r['file_end']] for r in refs) == oracle['email'].encode()
    for r in refs:
        assert r['file_start'] == r['packet']['data_offset']+r['frame_start']
        assert r['file_end']-r['file_start'] == r['stream_end']-r['stream_start']
        assert r['tcp_seq_end']-r['tcp_seq_start'] == r['frame_end']-r['frame_start']
    assert result['verification']['status'] == 'recorded_source_ranges'
    assert not result['source_ranges_truncated']
    assert 'retransmission' in result['stream']['diagnostics']
    assert oracle['email'] not in json.dumps(result)
    with pytest.raises(KeyError):
        investigation(conn,message_id=report['http_evidence'][-1]['http_message_id'],field_id=fid)
    with pytest.raises(ValueError):
        investigation(conn,message_id="x' OR 1=1--")


def test_transformed_field_only_supports_source_not_decoded_span(evidence):
    path, _, report, conn = evidence
    message = report['http_evidence'][-1]
    field = next(f for f in report['field_evidence'] if f['http_message_id']==message['http_message_id'] and f['source_category']=='json_body')
    result = investigation(conn,message_id=message['http_message_id'],field_id=field['field_id'])
    assert result['selected_field']['granularity']=='transformed_source_range'
    assert {'chunked_decode','gzip','json_parse'} <= set(result['selected_field']['transformations'])
    source = b''.join(path.read_bytes()[r['file_start']:r['file_end']] for r in result['source_ranges'])
    assert source == fixture.messages()[-1].split(b'\r\n\r\n',1)[1]
    assert b'reply@example.invalid' not in source


def test_opt_in_source_is_local_text_with_hash_verification(evidence):
    path, oracle, report, conn = evidence
    html = report['http_evidence'][2]['http_message_id']
    result = recover_content(conn,path,report['capture_evidence'],message_id=html)
    assert result['is_html'] and result['status']=='recovered'
    assert result['capture_sha256']==oracle['sha256']
    assert result['text'].encode()==fixture.messages()[2].split(b'\r\n\r\n',1)[1]
    assert '<script>' in result['text']  # JSON source only; frontend must use textContent.
    compressed = recover_content(conn,path,report['capture_evidence'],message_id=report['http_evidence'][-1]['http_message_id'])
    assert compressed['content_type']=='application/json'
    assert json.loads(compressed['text'])['full_name']=='Alex Fiction'
    with pytest.raises(ValueError):
        recover_content(conn,path,report['capture_evidence'],message_id=report['http_evidence'][0]['http_message_id'])
    raw=bytearray(path.read_bytes());raw[24]^=1;path.write_bytes(raw)
    with pytest.raises(ValueError,match='identity mismatch'):
        recover_content(conn,path,report['capture_evidence'],message_id=html)


@contextmanager
def server(retain=False):
    s=DashboardServer(('127.0.0.1',0),retain_capture_for_inspection=retain)
    thread=threading.Thread(target=s.serve_forever,daemon=True);thread.start()
    try: yield s
    finally: s.shutdown();s.server_close();thread.join(3)


def request(s,method,path,body=None,headers=None,auth=True):
    c=HTTPConnection('127.0.0.1',s.server_port,timeout=20)
    h={'X-Dashboard-Token':s.token} if auth else {}
    h.update(headers or {})
    c.request(method,path,body=body,headers=h)
    r=c.getresponse();data=r.read();out=(r.status,json.loads(data),dict(r.getheaders()));c.close();return out


def upload(s,path,request_id='investigation-demo'):
    code,data,_=request(s,'POST','/api/jobs',path.read_bytes(),{'X-Request-ID':request_id,'X-Capture-Name':'demo.pcap','Content-Type':'application/octet-stream'})
    assert code==202
    job=s.jobs.get(data['job_id']);job.thread.join(10)
    assert not job.thread.is_alive()
    return job


@pytest.mark.parametrize('retain',[False,True])
def test_http_auth_ack_job_isolation_retention_and_content(evidence,retain):
    path, _, report, _ = evidence
    mid=report['http_evidence'][2]['http_message_id']
    with server(retain) as s:
        job=upload(s,path)
        assert job.status=='completed'
        assert job.capture.exists() is retain
        base='/api/jobs/'+job.job_id
        assert request(s,'GET',base+'/conversations',auth=False)[0]==403
        code,result,_=request(s,'GET',base+'/conversations?limit=1')
        assert code==200 and result['total']==2
        code,result,_=request(s,'GET',base+'/investigation?message_id='+mid)
        assert code==200 and result['content_available'] is retain
        assert request(s,'GET',base+'/conversations?limit=101')[0]==400
        assert request(s,'GET',base+'/investigation?message_id=foreign')[0]==404
        assert request(s,'GET','/api/jobs/'+'f'*32+'/conversations')[0]==404
        body=json.dumps({'message_id':mid,'acknowledge_sensitive_content':True})
        h={'Content-Type':'application/json'}
        assert request(s,'POST',base+'/content',body,h,auth=False)[0]==403
        assert request(s,'POST',base+'/content',body,{**h,'Origin':'https://evil.invalid'})[0]==403
        assert request(s,'POST',base+'/content',json.dumps({'message_id':mid}),h)[0]==400
        assert request(s,'POST',base+'/content','[]',h)[0]==400
        code,result,headers=request(s,'POST',base+'/content',body,h)
        assert code==(200 if retain else 400)
        assert headers['Content-Type'].startswith('application/json')
        assert headers['Cache-Control']=='no-store'
        if retain:
            assert '<script>' in result['text']
            assert job.capture.stat().st_mode & 0o777 == 0o600
            # Another capture's identical message IDs are resolved only inside its job.
            modified=path.parent/'other.pcap'
            modified.write_bytes(path.read_bytes().replace(b'alex@example.invalid',b'zoey@example.invalid'))
            other=upload(s,modified,'investigation-second')
            assert other.status=='completed'
            code,result,_=request(s,'POST','/api/jobs/'+other.job_id+'/content',body,h)
            assert code==200 and 'zoey@example.invalid' in result['text'] and 'alex@example.invalid' not in result['text']
            job.capture.write_bytes(job.capture.read_bytes()+b'x')
            assert request(s,'POST',base+'/content',body,h)[0]==400
            job.updated=time.monotonic()-s.jobs.ttl-1
            assert request(s,'POST',base+'/content',body,h)[0]==404


def test_failure_cancel_retained_capture_never_exposed(evidence,monkeypatch):
    import packet_pii.jobs as jobs
    path, _, _, _ = evidence
    original=jobs.analyze_to_report
    entered=threading.Event();release=threading.Event()
    def blocked(*a,**kw):
        entered.set();assert release.wait(5)
        return original(*a,**kw)
    monkeypatch.setattr(jobs,'analyze_to_report',blocked)
    with server(True) as s:
        code,data,_=request(s,'POST','/api/jobs',path.read_bytes(),{'X-Request-ID':'cancel-source-demo','X-Capture-Name':'demo.pcap','Content-Type':'application/octet-stream'})
        assert code==202 and entered.wait(2)
        job=s.jobs.get(data['job_id']);base='/api/jobs/'+job.job_id
        assert request(s,'GET',base+'/conversations')[0]==400
        request(s,'POST',base+'/cancel');release.set();job.thread.join(10)
        assert job.status=='cancelled' and not list(job.directory.iterdir())
        assert request(s,'GET',base+'/conversations')[0]==400
    monkeypatch.setattr(jobs,'analyze_to_report',lambda *a,**kw: (_ for _ in ()).throw(ValueError('private contents')))
    with server(True) as s:
        job=upload(s,path)
        assert job.status=='failed' and not list(job.directory.iterdir())
        assert 'private contents' not in json.dumps(s.jobs.snapshot(job))


def test_h2_navigation_explicitly_has_no_response_source_view(tmp_path):
    from test_http2_evidence import client, headers, frame, encoder
    from test_network_evidence_integration import capture
    path=capture(tmp_path/'h2.pcap',client(headers(encoder(),end=False,extra=[('content-type','application/json')]),frame(0,1,1,b'{"email":"x@example.invalid"}')))
    report=analyze(path)
    with indexed(report) as conn:
        result=conversations(conn)
        message=result['items'][0]['messages'][0]
        assert message['protocol']=='h2' and message['http2_stream_id']==1
        assert message['pairing_status']=='unpaired'
        assert message['association_basis']=='http2_stream_id'
        with pytest.raises(ValueError,match='Only contiguous'):
            recover_content(conn,path,report['capture_evidence'],message_id=message['http_message_id'])


def test_source_range_limits_and_missing_source_fail_closed(evidence):
    path, _, report, conn=evidence
    mid=report['http_evidence'][2]['http_message_id']
    conn.execute('DELETE FROM source_intervals')
    result=investigation(conn,message_id=mid)
